class FfiConverterInt32: FfiConverter<int, int> {
    public static FfiConverterInt32 INSTANCE = new FfiConverterInt32();

    public override int Lift(int value) {
        return value;
    }

    public override int Read(BigEndianStream stream) {
        return stream.ReadInt();
    }

    public override int Lower(int value) {
        return value;
    }

    public override int AllocationSize(int value) {
        return 4;
    }

    public override void Write(int value, BigEndianStream stream) {
        stream.WriteInt(value);
    }
}



class FfiConverterUInt32: FfiConverter<uint, uint> {
    public static FfiConverterUInt32 INSTANCE = new FfiConverterUInt32();

    public override uint Lift(uint value) {
        return value;
    }

    public override uint Read(BigEndianStream stream) {
        return stream.ReadUInt();
    }

    public override uint Lower(uint value) {
        return value;
    }

    public override int AllocationSize(uint value) {
        return 4;
    }

    public override void Write(uint value, BigEndianStream stream) {
        stream.WriteUInt(value);
    }
}



class FfiConverterUInt64: FfiConverter<ulong, ulong> {
    public static FfiConverterUInt64 INSTANCE = new FfiConverterUInt64();

    public override ulong Lift(ulong value) {
        return value;
    }

    public override ulong Read(BigEndianStream stream) {
        return stream.ReadULong();
    }

    public override ulong Lower(ulong value) {
        return value;
    }

    public override int AllocationSize(ulong value) {
        return 8;
    }

    public override void Write(ulong value, BigEndianStream stream) {
        stream.WriteULong(value);
    }
}



class FfiConverterBoolean: FfiConverter<bool, sbyte> {
    public static FfiConverterBoolean INSTANCE = new FfiConverterBoolean();

    public override bool Lift(sbyte value) {
        return value != 0;
    }

    public override bool Read(BigEndianStream stream) {
        return Lift(stream.ReadSByte());
    }

    public override sbyte Lower(bool value) {
        return value ? (sbyte)1 : (sbyte)0;
    }

    public override int AllocationSize(bool value) {
        return (sbyte)1;
    }

    public override void Write(bool value, BigEndianStream stream) {
        stream.WriteSByte(Lower(value));
    }
}



class FfiConverterString: FfiConverter<string, RustBuffer> {
    public static FfiConverterString INSTANCE = new FfiConverterString();

    // Note: we don't inherit from FfiConverterRustBuffer, because we use a
    // special encoding when lowering/lifting.  We can use `RustBuffer.len` to
    // store our length and avoid writing it out to the buffer.
    public override string Lift(RustBuffer value) {
        try {
            var bytes = value.AsStream().ReadBytes(Convert.ToInt32(value.len));
            return System.Text.Encoding.UTF8.GetString(bytes);
        } finally {
            RustBuffer.Free(value);
        }
    }

    public override string Read(BigEndianStream stream) {
        var length = stream.ReadInt();
        var bytes = stream.ReadBytes(length);
        return System.Text.Encoding.UTF8.GetString(bytes);
    }

    public override RustBuffer Lower(string value) {
        var bytes = System.Text.Encoding.UTF8.GetBytes(value);
        var rbuf = RustBuffer.Alloc(bytes.Length);
        rbuf.AsWriteableStream().WriteBytes(bytes);
        return rbuf;
    }

    // TODO(CS)
    // We aren't sure exactly how many bytes our string will be once it's UTF-8
    // encoded.  Allocate 3 bytes per unicode codepoint which will always be
    // enough.
    public override int AllocationSize(string value) {
        const int sizeForLength = 4;
        var sizeForString = System.Text.Encoding.UTF8.GetByteCount(value);
        return sizeForLength + sizeForString;
    }

    public override void Write(string value, BigEndianStream stream) {
        var bytes = System.Text.Encoding.UTF8.GetBytes(value);
        stream.WriteInt(bytes.Length);
        stream.WriteBytes(bytes);
    }
}




class FfiConverterByteArray: FfiConverterRustBuffer<byte[]> {
    public static FfiConverterByteArray INSTANCE = new FfiConverterByteArray();

    public override byte[] Read(BigEndianStream stream) {
        var length = stream.ReadInt();
        return stream.ReadBytes(length);
    }

    public override int AllocationSize(byte[] value) {
        return 4 + value.Length;
    }

    public override void Write(byte[] value, BigEndianStream stream) {
        stream.WriteInt(value.Length);
        stream.WriteBytes(value);
    }
}



/// <summary>
/// Positive limits admitted by the canonical create/update validators.
/// </summary>
public record ActorLimits (
    PositiveU64 HandlerTimeoutMillis, 
    PositiveU64 MemoryBytes, 
    PositiveU64 CheckpointBytes
) {
}

class FfiConverterTypeActorLimits: FfiConverterRustBuffer<ActorLimits> {
    public static FfiConverterTypeActorLimits INSTANCE = new FfiConverterTypeActorLimits();

    public override ActorLimits Read(BigEndianStream stream) {
        return new ActorLimits(
            HandlerTimeoutMillis: FfiConverterTypePositiveU64.INSTANCE.Read(stream),
            MemoryBytes: FfiConverterTypePositiveU64.INSTANCE.Read(stream),
            CheckpointBytes: FfiConverterTypePositiveU64.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(ActorLimits value) {
        return 0
            + FfiConverterTypePositiveU64.INSTANCE.AllocationSize(value.HandlerTimeoutMillis)
            + FfiConverterTypePositiveU64.INSTANCE.AllocationSize(value.MemoryBytes)
            + FfiConverterTypePositiveU64.INSTANCE.AllocationSize(value.CheckpointBytes);
    }

    public override void Write(ActorLimits value, BigEndianStream stream) {
            FfiConverterTypePositiveU64.INSTANCE.Write(value.HandlerTimeoutMillis, stream);
            FfiConverterTypePositiveU64.INSTANCE.Write(value.MemoryBytes, stream);
            FfiConverterTypePositiveU64.INSTANCE.Write(value.CheckpointBytes, stream);
    }
}



/// <summary>
/// Lossless semantic view of a server Actor observation.
/// </summary>
public record ActorObservation (
    ActorId ActorId, 
    CodeSha256 CodeSha256, 
    string HomeRegion, 
    ActorState State, 
    SubscriptionObservation[] Subscriptions, 
    ulong? CheckpointUnixMillis, 
    ulong CheckpointEpoch, 
    ulong ConfigurationRevision
) {
}

class FfiConverterTypeActorObservation: FfiConverterRustBuffer<ActorObservation> {
    public static FfiConverterTypeActorObservation INSTANCE = new FfiConverterTypeActorObservation();

    public override ActorObservation Read(BigEndianStream stream) {
        return new ActorObservation(
            ActorId: FfiConverterTypeActorId.INSTANCE.Read(stream),
            CodeSha256: FfiConverterTypeCodeSha256.INSTANCE.Read(stream),
            HomeRegion: FfiConverterString.INSTANCE.Read(stream),
            State: FfiConverterTypeActorState.INSTANCE.Read(stream),
            Subscriptions: FfiConverterSequenceTypeSubscriptionObservation.INSTANCE.Read(stream),
            CheckpointUnixMillis: FfiConverterOptionalUInt64.INSTANCE.Read(stream),
            CheckpointEpoch: FfiConverterUInt64.INSTANCE.Read(stream),
            ConfigurationRevision: FfiConverterUInt64.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(ActorObservation value) {
        return 0
            + FfiConverterTypeActorId.INSTANCE.AllocationSize(value.ActorId)
            + FfiConverterTypeCodeSha256.INSTANCE.AllocationSize(value.CodeSha256)
            + FfiConverterString.INSTANCE.AllocationSize(value.HomeRegion)
            + FfiConverterTypeActorState.INSTANCE.AllocationSize(value.State)
            + FfiConverterSequenceTypeSubscriptionObservation.INSTANCE.AllocationSize(value.Subscriptions)
            + FfiConverterOptionalUInt64.INSTANCE.AllocationSize(value.CheckpointUnixMillis)
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.CheckpointEpoch)
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.ConfigurationRevision);
    }

    public override void Write(ActorObservation value, BigEndianStream stream) {
            FfiConverterTypeActorId.INSTANCE.Write(value.ActorId, stream);
            FfiConverterTypeCodeSha256.INSTANCE.Write(value.CodeSha256, stream);
            FfiConverterString.INSTANCE.Write(value.HomeRegion, stream);
            FfiConverterTypeActorState.INSTANCE.Write(value.State, stream);
            FfiConverterSequenceTypeSubscriptionObservation.INSTANCE.Write(value.Subscriptions, stream);
            FfiConverterOptionalUInt64.INSTANCE.Write(value.CheckpointUnixMillis, stream);
            FfiConverterUInt64.INSTANCE.Write(value.CheckpointEpoch, stream);
            FfiConverterUInt64.INSTANCE.Write(value.ConfigurationRevision, stream);
    }
}



