/// <summary>
/// Errors crossing the generated foreign-language boundary.
/// </summary>
public class BindingException: UniffiException {
    BindingException() : base() {}
    BindingException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    /// <summary>
    /// Endpoint, credential, or trust configuration was rejected by Rust.
    /// </summary>
    
    public class Configuration : BindingException {
        // Members
        public string @detailMessage;

        // Constructor
        public Configuration(
                string @detailMessage) : base(
                "@detailMessage" + "=" + @detailMessage) {

            this.@detailMessage = @detailMessage;
        }
    }
    
    /// <summary>
    /// The Rust-owned transport could not be constructed or reached.
    /// </summary>
    
    public class Transport : BindingException {
        // Members
        public string @detailMessage;

        // Constructor
        public Transport(
                string @detailMessage) : base(
                "@detailMessage" + "=" + @detailMessage) {

            this.@detailMessage = @detailMessage;
        }
    }
    
    /// <summary>
    /// The service rejected an operation.
    /// </summary>
    
    public class Service : BindingException {
        // Members
        public int @grpcCode;
        public int? @serviceCode;
        public string @detailMessage;

        // Constructor
        public Service(
                int @grpcCode, 
                int? @serviceCode, 
                string @detailMessage) : base(
                "@grpcCode" + "=" + @grpcCode+ ", " +
                "@serviceCode" + "=" + @serviceCode+ ", " +
                "@detailMessage" + "=" + @detailMessage) {

            this.@grpcCode = @grpcCode;

            this.@serviceCode = @serviceCode;

            this.@detailMessage = @detailMessage;
        }
    }
    
    /// <summary>
    /// Rust's canonical request validator rejected an operation.
    /// </summary>
    
    public class Contract : BindingException {
        // Members
        public string @detailMessage;

        // Constructor
        public Contract(
                string @detailMessage) : base(
                "@detailMessage" + "=" + @detailMessage) {

            this.@detailMessage = @detailMessage;
        }
    }
    
    /// <summary>
    /// Rust could not project a wire value into its semantic domain.
    /// </summary>
    
    public class Semantic : BindingException {
        // Members
        public string @detailMessage;

        // Constructor
        public Semantic(
                string @detailMessage) : base(
                "@detailMessage" + "=" + @detailMessage) {

            this.@detailMessage = @detailMessage;
        }
    }
    
    /// <summary>
    /// The Rust-owned operation observed cancellation.
    /// </summary>
    public class Cancelled : BindingException {
        public Cancelled() : base() {}
    }
    
    

    
}

class FfiConverterTypeBindingError : FfiConverterRustBuffer<BindingException>, CallStatusErrorHandler<BindingException> {
    public static FfiConverterTypeBindingError INSTANCE = new FfiConverterTypeBindingError();

    public override BindingException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new BindingException.Configuration(
                    FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new BindingException.Transport(
                    FfiConverterString.INSTANCE.Read(stream));
            case 3:
                return new BindingException.Service(
                    FfiConverterInt32.INSTANCE.Read(stream),
                    FfiConverterOptionalInt32.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream));
            case 4:
                return new BindingException.Contract(
                    FfiConverterString.INSTANCE.Read(stream));
            case 5:
                return new BindingException.Semantic(
                    FfiConverterString.INSTANCE.Read(stream));
            case 6:
                return new BindingException.Cancelled();
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeBindingError.Read()", value));
        }
    }

    public override int AllocationSize(BindingException value) {
        switch (value) {

            case BindingException.Configuration variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detailMessage);

            case BindingException.Transport variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detailMessage);

            case BindingException.Service variant_value:
                return 4
                    + FfiConverterInt32.INSTANCE.AllocationSize(variant_value.@grpcCode)
                    + FfiConverterOptionalInt32.INSTANCE.AllocationSize(variant_value.@serviceCode)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detailMessage);

            case BindingException.Contract variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detailMessage);

            case BindingException.Semantic variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detailMessage);

            case BindingException.Cancelled variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeBindingError.AllocationSize()", value));
        }
    }

    public override void Write(BindingException value, BigEndianStream stream) {
        switch (value) {
            case BindingException.Configuration variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@detailMessage, stream);
                break;
            case BindingException.Transport variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.@detailMessage, stream);
                break;
            case BindingException.Service variant_value:
                stream.WriteInt(3);
                FfiConverterInt32.INSTANCE.Write(variant_value.@grpcCode, stream);
                FfiConverterOptionalInt32.INSTANCE.Write(variant_value.@serviceCode, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@detailMessage, stream);
                break;
            case BindingException.Contract variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.@detailMessage, stream);
                break;
            case BindingException.Semantic variant_value:
                stream.WriteInt(5);
                FfiConverterString.INSTANCE.Write(variant_value.@detailMessage, stream);
                break;
            case BindingException.Cancelled variant_value:
                stream.WriteInt(6);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeBindingError.Write()", value));
        }
    }
}




